function resolveSeenCount_0Writes(seam: ISqlSeam, before: Snapshot, arrivals: IArrivalBatch): Observable<readonly SqlStatement[]> {
  const triggerRows = triggerOccurrences("set", "seen", before.seen, arrivals);
  if (triggerRows.length === 0) return of([]);
  return forkJoin(triggerRows.map((arrival) => seam.runner.execute(seam.db, { sql: EDGE_SEEN_COUNT_0_PROJECT_SQL, args: bindArgs(arrival.row) }))).pipe(
    map((results) => {
      const written: SqlStatement[] = [];
      for (const result of results) {
        const projectedRows = result.rows.map((row) => EDGE_SEEN_COUNT_0_HEAD_COLUMNS.map((column) => row[column] as IRowValue) as IRow);
        for (const projectedRow of projectedRows) {
          written.push({ sql: EDGE_SEEN_COUNT_0_WRITE_SQL, args: bindArgs(projectedRow) });
        }
      }
      return written;
    }),
  );
}

