function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const heard = multisetDiff(before.heard, after.heard);
  const heard_count = multisetDiff(before.heard_count, after.heard_count);
  const seen = multisetDiff(before.seen, after.seen);
  const seen_count = multisetDiff(before.seen_count, after.seen_count);
  return {
    rels: [
      { rel: "heard", add: heard.add, del: heard.del },
      { rel: "heard_count", add: heard_count.add, del: heard_count.del },
      { rel: "seen", add: seen.add, del: seen.del },
      { rel: "seen_count", add: seen_count.add, del: seen_count.del },
    ],
    carryPending: heard_count.add.length > 0 || heard_count.del.length > 0 || seen_count.add.length > 0 || seen_count.del.length > 0,
  };
}

